#!/usr/bin/env node
'use strict';

const { spawn, spawnSync } = require('child_process');
const {
  appendFileSync,
  chmodSync,
  closeSync,
  createWriteStream,
  existsSync,
  mkdirSync,
  openSync,
  readdirSync,
  readFileSync,
  renameSync,
  statSync,
  unlinkSync,
  writeFileSync,
} = require('fs');
const { homedir } = require('os');
const { join, resolve } = require('path');
const { pipeline } = require('stream/promises');
const { pathToFileURL } = require('url');

const GRADLE_DISTRIBUTION_URL = 'https://static.locofy.ai/android/gradle-8.13-bin.zip';

const EXIT_CODE = {
  SUCCESS: 0,
  FAILED: 1,
  TIMEOUT: 2,
  ERROR: 3,
};

function parseArgs(args) {
  const options = {
    projectDir: '',
    module: 'app',
    variant: 'debug',
    timeout: 900,
  };

  for (let index = 0; index < args.length; index += 1) {
    const arg = args[index];
    if (!['--project-dir', '--module', '--variant', '--timeout'].includes(arg)) {
      throw new Error(`Unknown arg: ${arg}`);
    }

    const value = args[index + 1];
    if (value === undefined) {
      throw new Error(`Missing value for ${arg}`);
    }
    index += 1;

    if (arg === '--project-dir') options.projectDir = value;
    if (arg === '--module') options.module = value;
    if (arg === '--variant') options.variant = value;
    if (arg === '--timeout') {
      if (
        !/^\d+$/.test(value) ||
        !Number.isSafeInteger(Number(value)) ||
        Number(value) <= 0 ||
        Number(value) > 2147483
      ) {
        throw new Error('--timeout must be an integer between 1 and 2147483 seconds');
      }
      options.timeout = Number(value);
    }
  }

  if (!options.projectDir) {
    throw new Error('Missing --project-dir');
  }

  options.module = options.module.replace(/^:+|:+$/g, '');
  if (!/^[A-Za-z0-9_.-]+(?::[A-Za-z0-9_.-]+)*$/.test(options.module)) {
    throw new Error('--module must be a Gradle module path such as app or feature:home');
  }
  if (!/^[A-Za-z][A-Za-z0-9]*$/.test(options.variant)) {
    throw new Error('--variant must contain only letters and numbers and start with a letter');
  }

  return options;
}

function terminateProcessTree(child, force, logFile) {
  if (!child.pid) return;

  if (process.platform === 'win32') {
    const result = spawnSync('taskkill.exe', ['/pid', String(child.pid), '/t', '/f'], {
      encoding: 'utf8',
      windowsHide: true,
    });
    if (result.error || result.status !== 0) {
      const details =
        result.error?.message || result.stderr?.trim() || `exit code ${result.status}`;
      appendFileSync(logFile, `Unable to terminate Gradle process tree: ${details}\n`, 'utf8');
      try {
        child.kill('SIGKILL');
      } catch {
        // The wrapper already exited.
      }
    }
    return;
  }

  try {
    process.kill(-child.pid, force ? 'SIGKILL' : 'SIGTERM');
  } catch {
    try {
      child.kill(force ? 'SIGKILL' : 'SIGTERM');
    } catch {
      // The process already exited.
    }
  }
}

function findGradleRoot(projectDir, wrapperName) {
  const queue = [{ directory: projectDir, depth: 0 }];

  while (queue.length > 0) {
    const current = queue.shift();
    const wrapper = join(current.directory, wrapperName);
    if (existsSync(wrapper) && statSync(wrapper).isFile()) {
      return current.directory;
    }
    if (current.depth === 2) continue;

    let entries = [];
    try {
      entries = readdirSync(current.directory, { withFileTypes: true });
    } catch {
      continue;
    }
    entries
      .filter(
        (entry) =>
          entry.isDirectory() && !['.git', '.locofy', 'build', 'node_modules'].includes(entry.name),
      )
      .sort((left, right) => left.name.localeCompare(right.name))
      .forEach((entry) =>
        queue.push({
          directory: join(current.directory, entry.name),
          depth: current.depth + 1,
        }),
      );
  }

  return '';
}

function findBundledJavaHome(environment) {
  const javaExecutable = process.platform === 'win32' ? 'java.exe' : 'java';
  const candidates = [];

  function add(directory) {
    if (directory && !candidates.includes(directory)) candidates.push(directory);
  }

  function addInstallations(parentDirectory) {
    let entries = [];
    try {
      entries = readdirSync(parentDirectory, { withFileTypes: true });
    } catch {
      return;
    }
    entries
      .filter((entry) => entry.isDirectory())
      .sort((left, right) => right.name.localeCompare(left.name, undefined, { numeric: true }))
      .forEach((entry) => add(join(parentDirectory, entry.name)));
  }

  if (process.platform === 'win32') {
    const programFiles = environment.ProgramFiles || 'C:\\Program Files';
    add(join(programFiles, 'Android', 'Android Studio', 'jbr'));
    add(join(programFiles, 'Android', 'Android Studio', 'jre'));
    if (environment.LOCALAPPDATA) {
      add(join(environment.LOCALAPPDATA, 'Programs', 'Android Studio', 'jbr'));
    }
    addInstallations(join(programFiles, 'Java'));
    addInstallations(join(programFiles, 'Eclipse Adoptium'));
    addInstallations(join(programFiles, 'Microsoft'));
  } else if (process.platform === 'darwin') {
    add('/Applications/Android Studio.app/Contents/jbr/Contents/Home');
    add('/Applications/Android Studio.app/Contents/jre/Contents/Home');
  } else {
    add('/opt/android-studio/jbr');
    add('/usr/local/android-studio/jbr');
    add(join(homedir(), 'android-studio', 'jbr'));
  }
  add(environment.JAVA_HOME);

  return candidates.find((directory) => existsSync(join(directory, 'bin', javaExecutable))) || '';
}

function androidEnvironment(gradleDir) {
  const env = { ...process.env };
  const javaHome = findBundledJavaHome(env);
  if (javaHome) env.JAVA_HOME = javaHome;
  let sdk = env.ANDROID_HOME || env.ANDROID_SDK_ROOT || '';

  if (!sdk) {
    const localProperties = join(gradleDir, 'local.properties');
    if (existsSync(localProperties)) {
      const match = readFileSync(localProperties, 'utf8').match(/^sdk\.dir=(.*)$/m);
      if (match) {
        sdk = match[1].trim().replace(/\\:/g, ':').replace(/\\\\/g, '\\').replace(/\\ /g, ' ');
      }
    }
  }

  if (!sdk) {
    if (process.platform === 'darwin') sdk = join(homedir(), 'Library', 'Android', 'sdk');
    if (process.platform === 'win32') {
      sdk = env.LOCALAPPDATA
        ? join(env.LOCALAPPDATA, 'Android', 'Sdk')
        : join(homedir(), 'AppData', 'Local', 'Android', 'Sdk');
    }
    if (process.platform === 'linux') sdk = join(homedir(), 'Android', 'Sdk');
  }

  if (sdk) {
    env.ANDROID_HOME = sdk;
    env.ANDROID_SDK_ROOT = sdk;
  }
  return env;
}

function findBuiltApk(moduleDir, variant) {
  const apkRoot = join(moduleDir, 'build', 'outputs', 'apk');
  const candidates = [];

  function visit(directory) {
    let entries = [];
    try {
      entries = readdirSync(directory, { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries) {
      const file = join(directory, entry.name);
      if (entry.isDirectory()) visit(file);
      if (
        entry.isFile() &&
        entry.name.toLowerCase().endsWith('.apk') &&
        !entry.name.toLowerCase().includes('androidtest')
      ) {
        candidates.push(file);
      }
    }
  }

  visit(apkRoot);
  const variantKey = variant.toLowerCase();
  return (
    candidates
      .filter((file) =>
        file
          .slice(apkRoot.length)
          .toLowerCase()
          .replace(/[^a-z0-9]/g, '')
          .includes(variantKey),
      )
      .sort((left, right) => {
        const modified = statSync(right).mtimeMs - statSync(left).mtimeMs;
        return modified || left.localeCompare(right);
      })[0] || ''
  );
}

function report(logFile, message = '') {
  console.log(message);
  appendFileSync(logFile, `${message}\n`, 'utf8');
}

async function downloadGradleDistribution(url, temporaryPath, finalPath) {
  try {
    const response = await fetch(url);
    if (!response.ok) {
      throw new Error(`Gradle download failed with HTTP status ${response.status}`);
    }

    await pipeline(response.body, createWriteStream(temporaryPath));
    renameSync(temporaryPath, finalPath);
  } catch (error) {
    if (existsSync(temporaryPath)) unlinkSync(temporaryPath);
    throw error;
  }
}

function runGradle({ wrapper, gradleDir, gradleHome, environment, args, timeout, logFile }) {
  return new Promise((resolveResult) => {
    const isWindows = process.platform === 'win32';
    const logDescriptor = openSync(logFile, 'a');

    // Batch files require cmd.exe. The command line contains only the fixed
    // wrapper name and validated Gradle arguments; the potentially spaced
    // project path stays in cwd. Other platforms execute the wrapper directly.
    const command = isWindows ? process.env.ComSpec || 'cmd.exe' : wrapper;
    const commandArgs = isWindows ? ['/d', '/s', '/c', ['gradlew.bat', ...args].join(' ')] : args;
    let child;
    try {
      child = spawn(command, commandArgs, {
        cwd: gradleDir,
        // POSIX needs a separate process group for timeout cleanup. On Windows,
        // detached children receive their own console window; taskkill can
        // terminate the attached process tree without detaching it.
        detached: !isWindows,
        env: environment,
        shell: false,
        // Redirect at the OS level so Gradle and all descendants inherit the
        // same log destination. Pipe listeners can lose output or keep the
        // runner alive when a descendant retains a pipe handle.
        stdio: ['ignore', logDescriptor, logDescriptor],
        windowsHide: true,
      });
    } catch (error) {
      closeSync(logDescriptor);
      resolveResult({
        code: null,
        signal: null,
        spawnError: error,
        timedOut: false,
      });
      return;
    }

    let spawnError;
    let timedOut = false;
    let forceKillTimer;

    child.on('error', (error) => {
      spawnError = error;
      appendFileSync(logFile, `\nUnable to start Gradle: ${error.message}\n`, 'utf8');
    });

    const timeoutTimer = setTimeout(() => {
      timedOut = true;
      terminateProcessTree(child, false, logFile);
      forceKillTimer = setTimeout(() => terminateProcessTree(child, true, logFile), 1500);
    }, timeout * 1000);

    child.on('close', (code, signal) => {
      clearTimeout(timeoutTimer);
      if (forceKillTimer) clearTimeout(forceKillTimer);
      closeSync(logDescriptor);
      resolveResult({
        code,
        signal,
        spawnError,
        timedOut,
      });
    });
  });
}

function printFailureDetails(logFile) {
  const log = readFileSync(logFile, 'utf8');

  if (/java\.lang\.IllegalArgumentException.*JavaVersion/i.test(log)) {
    report(logFile, 'ERROR_TYPE:GRADLE_JAVA_VERSION_INCOMPATIBILITY');
  }

  const lines = log.split(/\r?\n/);
  const compilerErrors = lines.filter(
    (line) =>
      /^\s*e:\s+file:\/\//.test(line) ||
      /\.(?:kt|java):\d+(?::\d+)?:?\s*(?:error:|warning:)/i.test(line),
  );
  const usefulLines =
    compilerErrors.length > 0
      ? compilerErrors
      : lines.filter(
          (line) =>
            /^\s*(?:FAILURE:|\* What went wrong:|> Task .* FAILED)/.test(line) ||
            /\berror:/i.test(line),
        );

  if (usefulLines.length > 0) {
    report(logFile, `ERROR_COUNT:${usefulLines.length}`);
    report(logFile, '=== BUILD ERRORS ===');
    for (const line of usefulLines.slice(-30)) report(logFile, line);
    report(logFile, '====================');
  } else {
    report(logFile, 'Build failed without structured compiler errors.');
  }
}

async function main() {
  let options;
  try {
    options = parseArgs(process.argv.slice(2));
  } catch (error) {
    console.log('BUILD_STATUS:ERROR');
    console.log(error.message);
    process.exitCode = EXIT_CODE.ERROR;
    return;
  }

  const projectDir = resolve(options.projectDir);
  if (!existsSync(projectDir) || !statSync(projectDir).isDirectory()) {
    console.log('BUILD_STATUS:ERROR');
    console.log(`Project directory not found: ${projectDir}`);
    process.exitCode = EXIT_CODE.ERROR;
    return;
  }

  const wrapperName = process.platform === 'win32' ? 'gradlew.bat' : 'gradlew';
  const gradleDir = findGradleRoot(projectDir, wrapperName);
  if (!gradleDir) {
    console.log('BUILD_STATUS:ERROR');
    console.log(`No ${wrapperName} found within ${projectDir}`);
    process.exitCode = EXIT_CODE.ERROR;
    return;
  }
  const wrapper = join(gradleDir, wrapperName);

  const moduleDir = join(gradleDir, ...options.module.split(':'));
  if (!existsSync(moduleDir) || !statSync(moduleDir).isDirectory()) {
    console.log('BUILD_STATUS:ERROR');
    console.log(`Module directory '${options.module}' not found in ${gradleDir}`);
    process.exitCode = EXIT_CODE.ERROR;
    return;
  }

  if (process.platform !== 'win32') {
    chmodSync(wrapper, statSync(wrapper).mode | 0o100);
  }

  const gradleHome = join(projectDir, '.locofy', '.gradle-home');
  const gradleDistributionDir = join(gradleDir, '.locofy', 'gradle');
  const configuredGradlePath = process.env.LOCOFY_GRADLE_PATH
    ? resolve(process.env.LOCOFY_GRADLE_PATH)
    : '';
  const useConfiguredGradle =
    configuredGradlePath &&
    existsSync(configuredGradlePath) &&
    statSync(configuredGradlePath).isFile();
  const gradleDistribution = useConfiguredGradle
    ? configuredGradlePath
    : join(gradleDistributionDir, 'gradle-8.13-bin.zip');
  const temporaryGradleDistribution = `${gradleDistribution}.part`;
  const wrapperProperties = join(gradleDir, 'gradle', 'wrapper', 'gradle-wrapper.properties');
  const logDir = join(projectDir, '.locofy', 'agent', 'build-logs');
  const environment = androidEnvironment(gradleDir);
  mkdirSync(gradleHome, { recursive: true });
  mkdirSync(gradleDistributionDir, { recursive: true });
  mkdirSync(logDir, { recursive: true });
  const timestamp = new Date().toISOString().replace(/[-:.TZ]/g, '');
  const logFile = join(logDir, `build_${timestamp}.log`);
  const variant = options.variant[0].toUpperCase() + options.variant.slice(1);
  const task = `:${options.module}:assemble${variant}`;
  const gradleArgs = [
    task,
    '--no-daemon',
    '--console=plain',
    '--stacktrace',
    '-Dorg.gradle.daemon=false',
    '-Dkotlin.daemon.enabled=false',
  ];

  report(logFile, `BUILD_CONFIG:project=${projectDir}`);
  report(logFile, `BUILD_CONFIG:gradleRoot=${gradleDir}`);
  report(logFile, `BUILD_CONFIG:wrapper=${wrapperName}`);
  report(logFile, `BUILD_CONFIG:module=${options.module}`);
  report(logFile, `BUILD_CONFIG:variant=${options.variant}`);
  report(logFile, `BUILD_CONFIG:timeout=${options.timeout}s`);
  report(logFile, `BUILD_CONFIG:gradleDistribution=${gradleDistribution}`);
  report(logFile, `BUILD_CONFIG:javaHome=${environment.JAVA_HOME || 'PATH'}`);
  report(logFile, `BUILD_CONFIG:log=${logFile}`);
  report(logFile, '---');

  let result;
  let runError;
  let restoreError;
  let originalProperties;
  try {
    if (!existsSync(wrapperProperties) || !statSync(wrapperProperties).isFile()) {
      throw new Error(`Gradle wrapper properties not found: ${wrapperProperties}`);
    }

    if (configuredGradlePath && !useConfiguredGradle) {
      report(
        logFile,
        `Configured Gradle distribution not found: ${configuredGradlePath}; using the default distribution instead.`,
      );
    }

    if (!useConfiguredGradle && !existsSync(gradleDistribution)) {
      report(logFile, `Downloading Gradle distribution to ${gradleDistribution}`);
      await downloadGradleDistribution(
        GRADLE_DISTRIBUTION_URL,
        temporaryGradleDistribution,
        gradleDistribution,
      );
    }

    originalProperties = readFileSync(wrapperProperties, 'utf8');
    if (!/^distributionUrl=.*$/m.test(originalProperties)) {
      throw new Error(`No distributionUrl found in ${wrapperProperties}`);
    }
    let patchedProperties = originalProperties.replace(
      /^distributionUrl=.*$/m,
      `distributionUrl=${pathToFileURL(gradleDistribution).href}`,
    );
    if (useConfiguredGradle) {
      patchedProperties = patchedProperties.replace(/^distributionSha256Sum=.*(?:\r?\n|$)/m, '');
    }

    writeFileSync(wrapperProperties, patchedProperties, 'utf8');
    result = await runGradle({
      wrapper,
      gradleDir,
      gradleHome,
      environment,
      args: gradleArgs,
      timeout: options.timeout,
      logFile,
    });
  } catch (error) {
    runError = error;
  } finally {
    if (originalProperties !== undefined) {
      try {
        writeFileSync(wrapperProperties, originalProperties, 'utf8');
      } catch (error) {
        restoreError = error;
      }
    }
  }

  if (restoreError) {
    report(logFile, 'BUILD_STATUS:ERROR');
    report(logFile, `Unable to restore Gradle wrapper properties: ${restoreError.message}`);
    report(logFile, `LOG:${logFile}`);
    process.exitCode = EXIT_CODE.ERROR;
    return;
  }

  if (runError) {
    report(logFile, 'BUILD_STATUS:ERROR');
    report(logFile, `Unable to prepare or run Gradle: ${runError.message}`);
    report(logFile, `LOG:${logFile}`);
    process.exitCode = EXIT_CODE.ERROR;
    return;
  }

  if (result.timedOut) {
    report(logFile, '---');
    report(logFile, 'BUILD_STATUS:TIMEOUT');
    report(logFile, `Build timed out after ${options.timeout}s.`);
    report(logFile, `LOG:${logFile}`);
    process.exitCode = EXIT_CODE.TIMEOUT;
    return;
  }

  if (result.spawnError) {
    report(logFile, '---');
    report(logFile, 'BUILD_STATUS:ERROR');
    report(logFile, `Unable to start Gradle: ${result.spawnError.message}`);
    report(logFile, `LOG:${logFile}`);
    process.exitCode = EXIT_CODE.ERROR;
    return;
  }

  if (result.code !== 0) {
    report(logFile, '---');
    report(logFile, 'BUILD_STATUS:FAILED');
    report(
      logFile,
      `Gradle exited with code ${result.code}${result.signal ? ` (${result.signal})` : ''}.`,
    );
    printFailureDetails(logFile);
    report(logFile, `LOG:${logFile}`);
    process.exitCode = EXIT_CODE.FAILED;
    return;
  }

  const apk = findBuiltApk(moduleDir, options.variant);
  if (!apk) {
    report(logFile, '---');
    report(logFile, 'BUILD_STATUS:ERROR');
    report(
      logFile,
      `Build succeeded but no ${options.variant} APK was found under ${join(
        moduleDir,
        'build',
        'outputs',
        'apk',
      )}.`,
    );
    report(logFile, `LOG:${logFile}`);
    process.exitCode = EXIT_CODE.ERROR;
    return;
  }

  report(logFile, '---');
  report(logFile, 'BUILD_STATUS:SUCCESS');
  report(logFile, 'Build succeeded.');
  report(logFile, `APK_PATH:${resolve(apk)}`);
  report(logFile, `LOG:${logFile}`);
  process.exitCode = EXIT_CODE.SUCCESS;
}

main().catch((error) => {
  console.log('BUILD_STATUS:ERROR');
  console.log(error instanceof Error ? error.message : String(error));
  process.exitCode = EXIT_CODE.ERROR;
});
